function redeemDepositsAndInternalBalances(...) external payable fundsSafu noSupplyChange nonReentrant {
    verifyDepositsAndInternalBalances(owner, deposits, internalBalances, ownerRoots, proof); // static merkle proof, no nonce
    verifySignature(owner, reciever, deadline, signature);                                  // static EIP-712, no nonce
    uint256 accountStalk;
    for (...) accountStalk += addMigratedDepositsToAccount(reciever, deposits[i]);
    setStalk(reciever, accountStalk, ownerRoots); // setStalk does stalk += / roots += each call
}
